# ============================================================
# Model loading
# ============================================================

def load_json(path: Path) -> dict[str, Any]:
    """
    Safely load model metadata.
    """
    if not path.exists():
        return {}

    try:
        with open(path, "r", encoding="utf-8") as f:
            return json.load(f)
    except Exception:
        return {}


def load_text_model() -> tuple[Any | None, dict[str, Any], str | None]:
    """
    Load the trained text model and metadata.

    Returns:
        model, metadata, error_message
    """
    if not MODEL_PATH.exists():
        return (
            None,
            {},
            (
                f"Text model not found:\n{MODEL_PATH}\n\n"
                "Please train the text model first by running:\n"
                "python train_text_model.py"
            ),
        )

    try:
        model = joblib.load(MODEL_PATH)
        metadata = load_json(META_PATH)
        return model, metadata, None

    except Exception as exc:
        return (
            None,
            {},
            f"Failed to load text model:\n{exc}",
        )


TEXT_MODEL, TEXT_META, MODEL_LOAD_ERROR = load_text_model()


# ============================================================
# General utilities
# ============================================================

def timestamp_for_filename() -> str:
    """
    Return a filesystem-safe timestamp.
    """
    return datetime.now().strftime("%Y%m%d_%H%M%S")


def tokenize_text(text: str) -> list[str]:
    """
    Convert text into lowercase word tokens for lexical sentiment scoring.
    """
    return re.findall(r"[a-zA-Z']+", str(text).lower())


def get_model_classes(model: Any) -> list[str]:
    """
    Extract class order from the trained scikit-learn pipeline.
    """
    if model is None:
        return BEHAVIOUR_CLASSES

    classes = list(getattr(model, "classes_", []))

    if not classes and hasattr(model, "named_steps"):
        final_estimator = list(model.named_steps.values())[-1]
        classes = list(getattr(final_estimator, "classes_", []))

    if not classes:
        classes = BEHAVIOUR_CLASSES

    return [str(label) for label in classes]


def normalise_scores(scores: dict[str, float] | None) -> dict[str, float]:
    """
    Ensure probability scores are valid and sum to 1.
    """
    if not scores:
        return {
            label: 1.0 / len(BEHAVIOUR_CLASSES)
            for label in BEHAVIOUR_CLASSES
        }

    clean = {
        label: max(float(scores.get(label, 0.0)), 0.0)
        for label in BEHAVIOUR_CLASSES
    }

    total = sum(clean.values())

    if total <= 0:
        return {
            label: 1.0 / len(BEHAVIOUR_CLASSES)
            for label in BEHAVIOUR_CLASSES
        }

    return {
        label: value / total
        for label, value in clean.items()
    }


def get_best_label(scores: dict[str, float]) -> str:
    """
    Return the class with the highest score.
    """
    scores = normalise_scores(scores)
    return max(scores, key=scores.get)


def safe_float(value: Any) -> float | None:
    """
    Convert value to float if possible.
    """
    try:
        return float(value)
    except Exception:
        return None


def format_percent(value: float) -> str:
    """
    Convert probability value into percentage string.
    """
    safe = max(0.0, min(1.0, float(value)))
    return f"{safe * 100:.2f}%"


def format_scores_decimal(scores: dict[str, float]) -> str:
    """
    Format behaviour scores as decimal probabilities.
    """
    scores = normalise_scores(scores)

    lines = []

    for label, score in sorted(
        scores.items(),
        key=lambda item: item[1],
        reverse=True,
    ):
        lines.append(f"  {label}: {score:.4f}")

    return "\n".join(lines)


def format_scores_percent(scores: dict[str, float]) -> str:
    """
    Format behaviour scores as percentages for presentation output.
    """
    scores = normalise_scores(scores)

    label_width = max(len(label) for label in BEHAVIOUR_CLASSES)

    lines = []

    for label, score in sorted(
        scores.items(),
        key=lambda item: item[1],
        reverse=True,
    ):
        display_label = label.capitalize()
        lines.append(f"{display_label:<{label_width + 2}} {format_percent(score):>8}")

    return "\n".join(lines)


def require_latest_result() -> dict[str, Any] | None:
    """
    Ensure that a latest text result exists before exporting.
    """
    if latest_text_result is None:
        messagebox.showwarning(
            "No Result Available",
            "No text prediction result is available yet.\n\n"
            "Please run a text prediction first.",
        )
        return None

    return latest_text_result


# ============================================================
# Sentiment prediction
# ============================================================

def predict_text_sentiment(text: str) -> dict[str, Any]:
    """
    Estimate sentiment using a lightweight rule-based lexical method.
    """
    tokens = tokenize_text(text)

    positive_hits = [token for token in tokens if token in POSITIVE_WORDS]
    negative_hits = [token for token in tokens if token in NEGATIVE_WORDS]

    positive_count = len(positive_hits)
    negative_count = len(negative_hits)

    total_sentiment_hits = positive_count + negative_count

    if total_sentiment_hits == 0:
        return {
            "sentiment_label": "neutral",
            "sentiment_score": 1.0,
            "positive_count": 0,
            "negative_count": 0,
            "positive_hits": [],
            "negative_hits": [],
            "method": "rule_based_lexical_sentiment",
        }

    raw_score = (positive_count - negative_count) / total_sentiment_hits

    if raw_score > 0.15:
        sentiment_label = "positive"
        sentiment_score = abs(raw_score)
    elif raw_score < -0.15:
        sentiment_label = "negative"
        sentiment_score = abs(raw_score)
    else:
        sentiment_label = "neutral"
        sentiment_score = 1.0 - abs(raw_score)

    return {
        "sentiment_label": sentiment_label,
        "sentiment_score": float(sentiment_score),
        "positive_count": int(positive_count),
        "negative_count": int(negative_count),
        "positive_hits": positive_hits,
        "negative_hits": negative_hits,
        "method": "rule_based_lexical_sentiment",
    }


# ============================================================
# Behaviour prediction
# ============================================================

def predict_text_behaviour(text: str) -> dict[str, Any]:
    """
    Predict behavioural state from live text using text_model.joblib.
    """
    if TEXT_MODEL is None:
        raise RuntimeError(MODEL_LOAD_ERROR or "Text model is not loaded.")

    cleaned_text = str(text).strip()

    if not cleaned_text:
        raise ValueError("No text was provided.")

    prediction = str(TEXT_MODEL.predict([cleaned_text])[0])

    scores: dict[str, float] = {}

    if hasattr(TEXT_MODEL, "predict_proba"):
        probabilities = TEXT_MODEL.predict_proba([cleaned_text])[0]
        model_classes = get_model_classes(TEXT_MODEL)

        for class_name, probability in zip(model_classes, probabilities):
            scores[str(class_name)] = float(probability)

    else:
        scores = {
            label: 1.0 if label == prediction else 0.0
            for label in BEHAVIOUR_CLASSES
        }

    behaviour_scores = normalise_scores(scores)

    if prediction not in behaviour_scores:
        prediction = get_best_label(behaviour_scores)

    confidence = behaviour_scores.get(prediction, 0.0)

    return {
        "input_text": cleaned_text,
        "predicted_behaviour": prediction,
        "confidence": float(confidence),
        "behaviour_scores": behaviour_scores,
        "model_path": str(MODEL_PATH),
        "metadata_path": str(META_PATH),
        "model_name": TEXT_META.get("model_name", "text_model.joblib"),
        "method": TEXT_META.get("method", "unknown"),
        "selected_classifier": TEXT_META.get("selected_classifier"),
        "selection_metric": TEXT_META.get("selection_metric"),
        "training_accuracy": TEXT_META.get("accuracy"),
        "training_macro_f1": TEXT_META.get("macro_f1"),
        "training_weighted_f1": TEXT_META.get("weighted_f1"),
        "classes": TEXT_META.get("classes", BEHAVIOUR_CLASSES),
    }


def analyse_live_text(text: str) -> dict[str, Any]:
    """
    Run both behavioural prediction and sentiment estimation.
    """
    behaviour_result = predict_text_behaviour(text)
    sentiment_result = predict_text_sentiment(text)

    return {
        "created_at": datetime.now().isoformat(timespec="seconds"),
        "modality": "text",
        **behaviour_result,
        "sentiment": sentiment_result,
        "methodological_note": (
            "The behavioural state is predicted using the trained text_model.joblib "
            "pipeline created by train_text_model.py. The model accepts raw live "
            "text input and returns one of the four SenseFuzeAI behavioural states. "
            "Sentiment is estimated separately using lightweight lexical scoring "
            "and should be interpreted as supporting evidence rather than the "
            "primary behavioural classifier."
        ),
    }


# ============================================================
# Presentation interpretation
# ============================================================

def build_brief_interpretation(result: dict[str, Any]) -> str:
    """
    Build concise, demo-friendly interpretation text.
    """
    prediction = str(result.get("predicted_behaviour", "unknown"))
    sentiment = result.get("sentiment", {})
    input_text = str(result.get("input_text", "")).lower()

    sentiment_label = sentiment.get("sentiment_label", "neutral")

    if prediction == "focused":
        return (
            "The system classifies the text as focused because the wording is most "
            "consistent with concentration, task engagement, or stable progress."
        )

    if prediction == "distracted":
        if any(term in input_text for term in ["phone", "tabs", "scrolling", "messages", "multitasking"]):
            return (
                "The system classifies the text as distracted because the wording "
                "suggests attention switching, device checking, or competing tasks."
            )

        return (
            "The system classifies the text as distracted because the semantic cues "
            "suggest reduced attention or difficulty staying on task."
        )

    if prediction == "fatigued":
        if any(term in input_text for term in ["tired", "sleepy", "drained", "exhausted", "slow"]):
            return (
                "The system classifies the text as fatigued because the wording "
                "contains cues of tiredness, low energy, or reduced alertness."
            )

        return (
            "The system classifies the text as fatigued because the semantic pattern "
            "is most consistent with low energy or reduced cognitive stamina."
        )

    if prediction == "overloaded":
        if any(term in input_text for term in ["deadline", "deadlines", "overwhelmed", "too much", "pressure", "stress"]):
            return (
                "The system classifies the text as overloaded because the wording "
                "suggests high workload, pressure, deadlines, or cognitive strain."
            )

        return (
            "The system classifies the text as overloaded because the semantic cues "
            "suggest excessive task demand or pressure."
        )

    return (
        "The system could not identify a strong text-based behavioural cue. "
        "The result should be interpreted as supporting evidence."
    )


def build_summary_text(result: dict[str, Any]) -> str:
    """
    Build presentation-friendly output.
    """
    prediction = str(result.get("predicted_behaviour", "unknown"))
    confidence = float(result.get("confidence", 0.0))
    scores = normalise_scores(result.get("behaviour_scores", {}))
    sentiment = result.get("sentiment", {})
    interpretation = result.get("brief_interpretation", "")

    sentiment_label = sentiment.get("sentiment_label", "unknown")
    sentiment_score = float(sentiment.get("sentiment_score", 0.0))

    display_prediction = prediction.upper()

    lines = [
        "SenseFuzeAI Live Text Behaviour Test",
        "=" * 50,
        "",
        f"Final Prediction: {display_prediction}",
        f"Confidence: {format_percent(confidence)}",
        f"Sentiment: {sentiment_label} ({format_percent(sentiment_score)})",
        "",
        "Final Behaviour Probabilities",
        "-" * 50,
        format_scores_percent(scores),
        "",
        "Brief Interpretation",
        "-" * 50,
        interpretation,
        "",
        "Text Evidence",
        "-" * 50,
        f"Input length: {len(str(result.get('input_text', '')))} characters",
        f"Sentiment method: {sentiment.get('method', 'unknown')}",
        f"Positive lexical hits: {sentiment.get('positive_count', 0)}",
        f"Negative lexical hits: {sentiment.get('negative_count', 0)}",
        "",
        "Technical Details",
        "-" * 50,
        "Full model metadata, class probabilities, sentiment lexical hits,",
        "and diagnostic information are available through the",
        "'Show Technical Details' button and export functions.",
        "",
        "Report Export",
        "-" * 50,
        "Full result available as JSON, CSV, or TXT report.",
    ]

    return "\n".join(lines)


def build_technical_text(result: dict[str, Any]) -> str:
    """
    Build full technical diagnostic output.
    """
    scores = normalise_scores(result.get("behaviour_scores", {}))
    sentiment = result.get("sentiment", {})

    lines = [
        "SenseFuzeAI Live Text Test - Technical Details",
        "=" * 70,
        "",
        f"Created at:              {result.get('created_at')}",
        f"Modality:                {result.get('modality')}",
        f"Predicted behaviour:     {result.get('predicted_behaviour')}",
        f"Confidence:              {float(result.get('confidence', 0.0)):.4f}",
        "",
        "Input text:",
        str(result.get("input_text", "")),
        "",
        "Behaviour class probabilities:",
        format_scores_decimal(scores),
        "",
        "Sentiment estimation:",
        f"  Sentiment label:       {sentiment.get('sentiment_label')}",
        f"  Sentiment score:       {float(sentiment.get('sentiment_score', 0.0)):.4f}",
        f"  Positive hits:         {sentiment.get('positive_count')}",
        f"  Negative hits:         {sentiment.get('negative_count')}",
        f"  Sentiment method:      {sentiment.get('method')}",
    ]

    positive_hits = sentiment.get("positive_hits", [])
    negative_hits = sentiment.get("negative_hits", [])

    if positive_hits:
        lines.append(f"  Positive words:        {', '.join(positive_hits)}")

    if negative_hits:
        lines.append(f"  Negative words:        {', '.join(negative_hits)}")

    lines.extend(
        [
            "",
            "Model information:",
            f"  Model name:            {result.get('model_name')}",
            f"  Method:                {result.get('method')}",
            f"  Selected classifier:   {result.get('selected_classifier')}",
            f"  Selection metric:      {result.get('selection_metric')}",
            f"  Model path:            {result.get('model_path')}",
            f"  Metadata path:         {result.get('metadata_path')}",
        ]
    )

    if result.get("training_accuracy") is not None:
        lines.append(
            f"  Training accuracy:     {float(result.get('training_accuracy')):.4f}"
        )

    if result.get("training_macro_f1") is not None:
        lines.append(
            f"  Training macro F1:     {float(result.get('training_macro_f1')):.4f}"
        )

    if result.get("training_weighted_f1") is not None:
        lines.append(
            f"  Training weighted F1:  {float(result.get('training_weighted_f1')):.4f}"
        )

    lines.extend(
        [
            "",
            "Full diagnostic JSON:",
            json.dumps(result, indent=2, default=str),
            "",
            "Methodological note:",
            str(result.get("methodological_note", "")),
        ]
    )

    return "\n".join(lines)


# ============================================================
# GUI actions
# ============================================================

def run_text_prediction() -> None:
    """
    Run live text behaviour and sentiment prediction.
    """
    global latest_text_result
    global latest_summary_text
    global latest_technical_text

    typed_text = input_box.get("1.0", tk.END).strip()

    output_box.delete("1.0", tk.END)

    if not typed_text:
        latest_text_result = None
        latest_summary_text = ""
        latest_technical_text = ""
        output_box.insert(tk.END, "Please enter some text.\n")
        return

    try:
        output_box.insert(
            tk.END,
            "Analysing text using trained text_model.joblib and sentiment scoring...\n\n",
        )
        root.update_idletasks()

        result = analyse_live_text(typed_text)
        result["brief_interpretation"] = build_brief_interpretation(result)

        latest_text_result = result
        latest_summary_text = build_summary_text(result)
        latest_technical_text = build_technical_text(result)

        output_box.delete("1.0", tk.END)
        output_box.insert(tk.END, latest_summary_text)

    except Exception as error:
        latest_text_result = None
        latest_summary_text = ""
        latest_technical_text = ""

        output_box.delete("1.0", tk.END)
        output_box.insert(tk.END, "Text model prediction failed.\n\n")
        output_box.insert(tk.END, str(error))


def show_technical_details() -> None:
    """
    Open a separate window showing detailed diagnostic output.
    """
    result = require_latest_result()

    if result is None:
        return

    details_window = tk.Toplevel(root)
    details_window.title("Text Technical Details")
    details_window.geometry("1020x780")

    title = tk.Label(
        details_window,
        text="Text Technical Details",
        font=("Arial", 16, "bold"),
    )
    title.pack(pady=10)

    details_box = scrolledtext.ScrolledText(
        details_window,
        width=120,
        height=40,
        font=("Consolas", 10),
    )
    details_box.pack(padx=12, pady=10, fill=tk.BOTH, expand=True)

    details_box.insert(tk.END, latest_technical_text)
    details_box.configure(state="disabled")

    close_button = tk.Button(
        details_window,
        text="Close",
        command=details_window.destroy,
        width=16,
    )
    close_button.pack(pady=8)


def reset_session() -> None:
    """
    Reset GUI state.
    """
    global latest_text_result
    global latest_summary_text
    global latest_technical_text

    latest_text_result = None
    latest_summary_text = ""
    latest_technical_text = ""

    input_box.delete("1.0", tk.END)
    output_box.delete("1.0", tk.END)
    output_box.insert(tk.END, "Session reset. Enter text to begin analysis.\n")


