# ============================================================
# Export functions
# ============================================================

def export_latest_result_json() -> None:
    """
    Export latest text result as JSON.
    """
    result = require_latest_result()

    if result is None:
        return

    output_path = EXPORT_DIR / f"text_result_{timestamp_for_filename()}.json"

    export_payload = {
        **result,
        "presentation_summary": latest_summary_text,
        "technical_report": latest_technical_text,
    }

    with open(output_path, "w", encoding="utf-8") as f:
        json.dump(export_payload, f, indent=4, default=str)

    messagebox.showinfo(
        "Export Complete",
        f"JSON result exported successfully:\n\n{output_path}",
    )


def export_latest_result_csv() -> None:
    """
    Export latest text result as one-row CSV summary.
    """
    result = require_latest_result()

    if result is None:
        return

    output_path = EXPORT_DIR / f"text_result_{timestamp_for_filename()}.csv"

    sentiment = result.get("sentiment", {})
    behaviour_scores = normalise_scores(result.get("behaviour_scores", {}))

    row: dict[str, Any] = {
        "created_at": result.get("created_at"),
        "modality": result.get("modality"),
        "input_text": result.get("input_text"),
        "predicted_behaviour": result.get("predicted_behaviour"),
        "behaviour_confidence": result.get("confidence"),
        "behaviour_confidence_percent": format_percent(float(result.get("confidence", 0.0))),
        "brief_interpretation": result.get("brief_interpretation"),
        "sentiment_label": sentiment.get("sentiment_label"),
        "sentiment_score": sentiment.get("sentiment_score"),
        "sentiment_score_percent": format_percent(float(sentiment.get("sentiment_score", 0.0))),
        "positive_count": sentiment.get("positive_count"),
        "negative_count": sentiment.get("negative_count"),
        "positive_hits": ", ".join(sentiment.get("positive_hits", [])),
        "negative_hits": ", ".join(sentiment.get("negative_hits", [])),
        "sentiment_method": sentiment.get("method"),
        "model_name": result.get("model_name"),
        "method": result.get("method"),
        "selected_classifier": result.get("selected_classifier"),
        "selection_metric": result.get("selection_metric"),
        "training_accuracy": result.get("training_accuracy"),
        "training_macro_f1": result.get("training_macro_f1"),
        "training_weighted_f1": result.get("training_weighted_f1"),
        "model_path": result.get("model_path"),
        "metadata_path": result.get("metadata_path"),
    }

    for label in BEHAVIOUR_CLASSES:
        row[f"prob_{label}"] = behaviour_scores.get(label, 0.0)

    with open(output_path, "w", encoding="utf-8", newline="") as f:
        writer = csv.DictWriter(f, fieldnames=list(row.keys()))
        writer.writeheader()
        writer.writerow(row)

    messagebox.showinfo(
        "Export Complete",
        f"CSV summary exported successfully:\n\n{output_path}",
    )


def export_latest_result_txt() -> None:
    """
    Export latest text result as a human-readable TXT report.
    """
    result = require_latest_result()

    if result is None:
        return

    output_path = EXPORT_DIR / f"text_report_{timestamp_for_filename()}.txt"

    with open(output_path, "w", encoding="utf-8") as f:
        f.write("SenseFuzeAI Live Text Behaviour Test Report\n")
        f.write("===========================================\n\n")

        f.write("Presentation Summary\n")
        f.write("--------------------\n")
        f.write(latest_summary_text)
        f.write("\n\n")

        f.write("Technical Diagnostic Details\n")
        f.write("----------------------------\n")
        f.write(latest_technical_text)
        f.write("\n")

    messagebox.showinfo(
        "Export Complete",
        f"Text report exported successfully:\n\n{output_path}",
    )


